INSERT INTO news_articles(title,description,content,url,author,source_name,category_name,published_at,sentiment) SELECT 'Universities explore responsible artificial intelligence tools','Example article for testing the analytics dashboard.','Universities are exploring artificial intelligence tools for research, accessibility, and personalized learning. Researchers emphasize transparency, privacy, and evaluation before broad deployment.','https://example.org/demo/ai-education','Editorial Desk','Demo Research Desk','Education',NOW()-INTERVAL 1 DAY,'POSITIVE' WHERE NOT EXISTS(SELECT 1 FROM news_articles WHERE title='Universities explore responsible artificial intelligence tools');
INSERT INTO news_articles(title,description,content,url,author,source_name,category_name,published_at,sentiment) SELECT 'New research studies energy use in data centres','Example record for technology and environment analysis.','Researchers are studying energy efficiency in data centres. The report discusses cooling systems, renewable energy, workload scheduling, and transparent measurement of environmental impact.','https://example.org/demo/data-centres','Science Desk','Science Brief','Environment',NOW()-INTERVAL 2 DAY,'NEUTRAL' WHERE NOT EXISTS(SELECT 1 FROM news_articles WHERE title='New research studies energy use in data centres');
INSERT INTO news_articles(title,description,content,url,author,source_name,category_name,published_at,sentiment) SELECT 'Small businesses adopt digital payment analytics','Example record for business topic analysis.','Small businesses are using digital payment analytics to understand customer demand. Owners report improved visibility, while analysts recommend protecting customer data and validating performance claims.','https://example.org/demo/payment-analytics','Business Desk','Campus Technology Review','Business',NOW()-INTERVAL 3 DAY,'POSITIVE' WHERE NOT EXISTS(SELECT 1 FROM news_articles WHERE title='Small businesses adopt digital payment analytics');
INSERT INTO social_posts(platform,author_name,post_text,post_url,likes_count,shares_count,comments_count,hashtag_text,sentiment,posted_at) SELECT 'Sample Dataset','Research Community','AI in education can improve accessibility when privacy and evaluation are handled responsibly.','https://example.org/demo/post/1',120,24,13,'#AI #Education #Research','POSITIVE',NOW()-INTERVAL 2 HOUR WHERE NOT EXISTS(SELECT 1 FROM social_posts WHERE post_text LIKE 'AI in education can improve accessibility%');
